window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b88e95be32265cf"]={"versions": [{"id": "FIG-7b88e95be32265cf", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt das Byte-Layout des DLT Extended Headers (Diagnostic Log and Trace Extended Header) gemäß der Protokollspezifikation AUTOSAR PRS LogAndTraceProtocol als tabellarische Bit-/Byte-Struktur dar. Es ordnet die logischen Header-Felder den physischen Byte-Positionen innerhalb des DLT-Nachrichtenformats zu. Im Protokoll-Stack schließt der Extended Header optional an den DLT Standard Header an, sofern das Extended-Header-Flag im Header Type gesetzt ist, und geht der Nutzlast (Payload) der DLT-Nachricht unmittelbar voraus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst insgesamt 10 Bytes (Byte 0 bis 9), aufgeteilt in vier Entitäten/Felder:</p>\n<ul class=\"fig-list\"><li><code>Message Info</code> (<code>MSIN</code>): 1 Byte an Offset 0 (dunkelblau hinterlegt).\n</li><li><code>Number of Arguments</code> (<code>NOAR</code>): 1 Byte an Offset 1 (hellblau hinterlegt).\n</li><li><code>Application ID</code> (<code>APID</code>): 4 Bytes an Offset 2 bis 5 (hellblau hinterlegt, zusammenhängendes 32-Bit-Feld / 4 ASCII-/Byte-Zeichen).\n</li><li><code>Context ID</code> (<code>CTID</code>): 4 Bytes an Offset 6 bis 9 (hellblau hinterlegt, zusammenhängendes 32-Bit-Feld / 4 ASCII-/Byte-Zeichen).\n</li></ul>\n<p class=\"fig-p\">Übergeordnete Schnittstellenbeziehung: Das Format definiert die serielle Bytereihenfolge des erweiterten Protokollheaders bei der Übertragung über Kommunikationskanäle (wie IPC, TCP/UDP/IP, Serial).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in strikter Byte-Reihenfolge von Offset 0 bis Offset 9:</p>\n<ol class=\"fig-list\"><li>Byte 0 (<code>MSIN</code>): Enthält Typ- und Steuerinformationen zur DLT-Nachricht.\n</li><li>Byte 1 (<code>NOAR</code>): Gibt die Anzahl der nachfolgenden Argumente in der Nutzlast an.\n</li><li>Bytes 2–5 (<code>APID</code>): Identifizieren die erzeugende Anwendung/Software-Komponente.\n</li><li>Bytes 6–9 (<code>CTID</code>): Identifizieren den Kontext bzw. Teilbereich innerhalb der Anwendung.\n</li></ol>\n<p class=\"fig-p\">Beim Empfang wertet der DLT-Daemon oder Trace-Client diese Felder sequenziell aus, um Nachrichtentyp, Komponentenursprung und Anzahl der Payload-Argumente zu decodieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß der normativen Anforderung <code>[PRS_Dlt_00617]</code> ist die Anordnung und Reihenfolge der vier Felder verbindlich einzuhalten. Die Gesamtlänge des Extended Headers ist fix auf 10 Bytes (80 Bits) festgelegt. Entwickler müssen sicherstellen, dass <code>MSIN</code> und <code>NOAR</code> jeweils als 8-Bit-Werte und <code>APID</code> sowie <code>CTID</code> jeweils als 32-Bit-Identifier (in der Regel 4 alphanumerische Zeichen) ohne Padding oder Lücken zwischen den Feldern serialisiert und deserialisiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b19c6ef029659480", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt das Byte-Layout des DLT Extended Headers (Diagnostic Log and Trace Extended Header) gemäß der Protokollspezifikation AUTOSAR PRS LogAndTraceProtocol als tabellarische Bit-/Byte-Struktur dar. Es ordnet die logischen Header-Felder den physischen Byte-Positionen innerhalb des DLT-Nachrichtenformats zu. Im Protokoll-Stack schließt der Extended Header optional an den DLT Standard Header an, sofern das Extended-Header-Flag im Header Type gesetzt ist, und geht der Nutzlast (Payload) der DLT-Nachricht unmittelbar voraus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Struktur umfasst insgesamt 10 Bytes (Byte 0 bis 9), aufgeteilt in vier Entitäten/Felder:</p>\n<ul class=\"fig-list\"><li><code>Message Info</code> (<code>MSIN</code>): 1 Byte an Offset 0 (dunkelblau hinterlegt).\n</li><li><code>Number of Arguments</code> (<code>NOAR</code>): 1 Byte an Offset 1 (hellblau hinterlegt).\n</li><li><code>Application ID</code> (<code>APID</code>): 4 Bytes an Offset 2 bis 5 (hellblau hinterlegt, zusammenhängendes 32-Bit-Feld / 4 ASCII-/Byte-Zeichen).\n</li><li><code>Context ID</code> (<code>CTID</code>): 4 Bytes an Offset 6 bis 9 (hellblau hinterlegt, zusammenhängendes 32-Bit-Feld / 4 ASCII-/Byte-Zeichen).\n</li></ul>\n<p class=\"fig-p\">Übergeordnete Schnittstellenbeziehung: Das Format definiert die serielle Bytereihenfolge des erweiterten Protokollheaders bei der Übertragung über Kommunikationskanäle (wie IPC, TCP/UDP/IP, Serial).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in strikter Byte-Reihenfolge von Offset 0 bis Offset 9:</p>\n<ol class=\"fig-list\"><li>Byte 0 (<code>MSIN</code>): Enthält Typ- und Steuerinformationen zur DLT-Nachricht.\n</li><li>Byte 1 (<code>NOAR</code>): Gibt die Anzahl der nachfolgenden Argumente in der Nutzlast an.\n</li><li>Bytes 2–5 (<code>APID</code>): Identifizieren die erzeugende Anwendung/Software-Komponente.\n</li><li>Bytes 6–9 (<code>CTID</code>): Identifizieren den Kontext bzw. Teilbereich innerhalb der Anwendung.\n</li></ol>\n<p class=\"fig-p\">Beim Empfang wertet der DLT-Daemon oder Trace-Client diese Felder sequenziell aus, um Nachrichtentyp, Komponentenursprung und Anzahl der Payload-Argumente zu decodieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß der normativen Anforderung <code>[PRS_Dlt_00617]</code> ist die Anordnung und Reihenfolge der vier Felder verbindlich einzuhalten. Die Gesamtlänge des Extended Headers ist fix auf 10 Bytes (80 Bits) festgelegt. Entwickler müssen sicherstellen, dass <code>MSIN</code> und <code>NOAR</code> jeweils als 8-Bit-Werte und <code>APID</code> sowie <code>CTID</code> jeweils als 32-Bit-Identifier (in der Regel 4 alphanumerische Zeichen) ohne Padding oder Lücken zwischen den Feldern serialisiert und deserialisiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7b88e95be32265cf", "to": "FIG-b19c6ef029659480", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
